        uint256 before = address(c).balance;
        require(before == fund);
        require(amount >= before);
        uint256 beforeThis = address(this).balance;
        c.multiplicate{value: amount}(address(this));
        assert(address(c).balance == 0 && address(this).balance == beforeThis + before + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // NOTE: this contract intentionally has NO receive/payable fallback,
    // so it rejects Ether transfers, making it a valid rejecting receiver.
    function run(uint256 fund, uint256 amount) public {
        require(fund > 0);
        require(amount >= fund);
        // fund c: fresh c has balance 0, so fund >= balance; receiver c accepts Ether.
        c.multiplicate{value: fund}(address(c));
        uint256 before = address(c).balance;
        require(before == fund);
        bool reverted;
        try c.multiplicate{value: amount}(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && address(c).balance == before);
    }
}
